import {escapeHtml as h} from './community-model.js';
const photo=p=>'<span class="chat-avatar">'+(p?.avatar_url&&/^https:\/\//.test(p.avatar_url)?'<img alt="" referrerpolicy="no-referrer" src="'+h(p.avatar_url)+'">':h((p?.display_name||p?.username||'?').charAt(0).toUpperCase()))+'</span>';
export function mountChat(cloud,{notify=()=>{}}={}){
 const button=document.createElement('button');button.className='message-button chat-toggle';button.type='button';button.setAttribute('aria-label','Messages');button.setAttribute('aria-haspopup','dialog');button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-10A8.5 8.5 0 0 1 10.5 3h2A8.5 8.5 0 0 1 21 11.5Z"/><path d="M7 10h9M7 14h6"/></svg><span class="chat-badge"></span>';
 document.querySelector('.header-tools').append(button);
 const dialog=document.createElement('dialog');dialog.className='chat-dialog';dialog.setAttribute('aria-labelledby','chatTitle');dialog.innerHTML='<header class="chat-top"><h2 id="chatTitle">Messages</h2><button type="button" class="chat-close" aria-label="Close messages">×</button></header><div class="chat-layout"><aside class="chat-people"><p class="chat-caption">Your friends</p><div class="chat-friends"></div><p class="chat-footnote">Follow each other to start a private conversation.</p></aside><section class="chat-thread"><div class="chat-peer"><button type="button" class="chat-back" aria-label="Back to conversations">←</button><div class="chat-peer-label">Choose a friend</div></div><button class="chat-older" type="button" hidden>Load earlier messages</button><div class="chat-messages" role="log" aria-label="Conversation" aria-live="polite"><p class="chat-empty">A good problem is better with a friend.</p></div><p class="chat-status" role="status"></p><form class="chat-compose"><label class="sr-only" for="chatBody">Message</label><textarea id="chatBody" rows="2" maxlength="2000" placeholder="Write a message…" disabled></textarea><button class="button primary" type="submit" disabled>Send</button></form></section></div>';
 document.body.append(dialog);const $=s=>dialog.querySelector(s),badge=button.querySelector('.chat-badge'),list=$('.chat-friends'),box=$('.chat-messages'),input=$('#chatBody'),send=$('.chat-compose button'),status=$('.chat-status');
 let owner=null,generation=0,peer=null,users=[],messages=[],canMessage=false,reading=false,sending=false,nonce=null,beforeMore=false;
 function unread(n){const count=Math.max(0,Number(n)||0);badge.textContent=count?count>99?'99+':String(count):'';button.setAttribute('aria-label',count?'Messages, '+count+' unread':'Messages');}
 function clear(){peer=null;users=[];messages=[];canMessage=false;reading=false;sending=false;nonce=null;beforeMore=false;input.value='';input.disabled=true;send.disabled=true;list.replaceChildren();box.replaceChildren();$('.chat-peer-label').textContent='Choose a friend';status.textContent='';$('.chat-older').hidden=true;dialog.classList.remove('thread-selected');unread(0);if(dialog.open)dialog.close();}
 function valid(ticket,user,target){return ticket===generation&&owner===user&&(!target||peer?.public_id===target);}
 function people(){list.innerHTML=users.length?users.map(p=>'<button type="button" data-peer="'+h(p.public_id)+'" class="chat-person '+(p.public_id===peer?.public_id?'selected':'')+'">'+photo(p)+'<span><strong>'+h(p.display_name||p.username||'Friend')+'</strong><small>'+h(p.username?'@'+p.username:'Conversation')+'</small></span>'+(Number(p.unread)?'<b>'+Number(p.unread)+'</b>':'')+'</button>').join(''):'<p class="chat-empty">No conversations yet. Find a friend in the top search and follow each other.</p>';list.querySelectorAll('[data-peer]').forEach(b=>b.onclick=()=>select(b.dataset.peer));}
 async function loadList(){if(!owner)return;const ticket=generation,user=owner;try{const r=await cloud.request('chat-list',{},user);if(!valid(ticket,user))return;users=r.users||[];people();}catch(e){if(valid(ticket,user))list.textContent=e.message;}}
 function render({scroll=false}={}){const atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<90;box.innerHTML=messages.length?messages.map(m=>'<article class="chat-bubble '+(m.isOwn?'own':'')+'"><p>'+h(m.body)+'</p><time datetime="'+h(m.created_at)+'">'+h(new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))+'</time></article>').join(''):'<p class="chat-empty">Say hello. Share an idea.</p>';if(scroll||atBottom)box.scrollTop=box.scrollHeight;$('.chat-older').hidden=!beforeMore;input.disabled=!canMessage||sending;send.disabled=!canMessage||sending||!input.value.trim();}
 async function markRead(){if(!peer||!dialog.open||document.visibilityState!=='visible'||!document.hasFocus())return;const through=messages.filter(m=>!m.isOwn).at(-1)?.id;if(!through)return;const ticket=generation,user=owner,target=peer.public_id;try{await cloud.request('chat-read',{target,through},user);if(valid(ticket,user,target)){const p=users.find(p=>p.public_id===target);if(p){p.unread=0;people();}}}catch{}}
 async function select(target){if(!owner)return;const ticket=++generation,user=owner;peer={public_id:target};messages=[];nonce=null;reading=false;sending=false;canMessage=false;input.value='';status.textContent='Loading conversation…';dialog.classList.add('thread-selected');render();people();try{const r=await cloud.request('chat-thread',{target},user);if(!valid(ticket,user,target))return;peer=r.peer;messages=r.messages||[];canMessage=r.canMessage===true;beforeMore=messages.length===50;$('.chat-peer-label').innerHTML=photo(peer)+'<span><strong>'+h(peer.display_name||'Friend')+'</strong><small>'+h(peer.username?'@'+peer.username:'Private conversation')+'</small></span>';status.textContent=canMessage?'': 'Both profiles must be discoverable and follow each other to send messages.';render({scroll:true});markRead();people();if(canMessage)input.focus();}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}}
 async function refresh(){if(!peer||!dialog.open||reading||!owner)return;const ticket=generation,user=owner,target=peer.public_id;reading=true;try{let more=true;while(more){const after=messages.at(-1)?.id||0,r=await cloud.request('chat-thread',{target,after},user);if(!valid(ticket,user,target))return;canMessage=r.canMessage===true;const fresh=(r.messages||[]).filter(m=>!messages.some(old=>old.id===m.id));messages.push(...fresh);messages.sort((a,b)=>a.id-b.id);more=after>0&&r.messages?.length===50&&fresh.length>0;render();}markRead();}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}finally{if(valid(ticket,user,target))reading=false;}}
 $('.chat-older').onclick=async()=>{if(!peer||reading||!messages.length)return;reading=true;const ticket=generation,user=owner,target=peer.public_id,oldHeight=box.scrollHeight;try{const r=await cloud.request('chat-thread',{target,before:messages[0].id},user);if(!valid(ticket,user,target))return;messages=[...(r.messages||[]),...messages];beforeMore=r.messages?.length===50;render();box.scrollTop=box.scrollHeight-oldHeight;}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}finally{if(valid(ticket,user,target))reading=false;}};
 input.oninput=()=>{nonce=null;send.disabled=sending||!canMessage||!input.value.trim();};
 $('.chat-compose').onsubmit=async e=>{e.preventDefault();if(!owner||!peer||!canMessage||sending||!input.value.trim())return;const ticket=generation,user=owner,target=peer.public_id,body=input.value.trim();nonce??=crypto.randomUUID();sending=true;render();status.textContent='Sending…';try{const r=await cloud.request('chat-send',{target,body,nonce},user);if(!valid(ticket,user,target))return;if(!messages.some(m=>m.id===r.message.id))messages.push(r.message);input.value='';nonce=null;status.textContent='';render({scroll:true});loadList();}catch(err){if(valid(ticket,user,target))status.textContent=err.message+' Your message is kept here; try Send again.';}finally{if(valid(ticket,user,target)){sending=false;render();input.focus();}}};
 async function open(target){if(!owner){notify('Sign in and create a profile to chat with friends.');return;}if(!dialog.open)dialog.showModal();if(target)await select(target);else if(peer)refresh();loadList();}
 button.onclick=()=>open();$('.chat-close').onclick=()=>dialog.close();$('.chat-back').onclick=()=>dialog.classList.remove('thread-selected');dialog.addEventListener('close',()=>{status.textContent='';});
 return{open,unread,setOwner(user){const next=user?.id||null;if(next===owner)return;generation++;owner=next;clear();},resume(){if(dialog.open){loadList();refresh();}},receive(event){if(!owner)return;if(dialog.open){loadList();if(peer?.public_id===event.actor?.public_id){refresh();return;}}notify(event.actor,{message:event.preview||'Sent you a message',open:()=>open(event.actor?.public_id)});}};
}
